/* 背景裝飾元素 */
.hall-scene::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: 
        repeating-linear-gradient(
            0deg,
            transparent,
            transparent 2px,
            rgba(79, 172, 254, 0.02) 2px,
            rgba(79, 172, 254, 0.02) 4px
        );
    pointer-events: none;
    opacity: 0.3;

.card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(79, 172, 254, 0.3), transparent);

.card-header::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 16px;
